const d = $input.first().json;
return [{ json: {
  ...d,
  iterations_sofia: 0,
  iterations_marcus: 0,
  sofia_feedback: '',
  marcus_feedback: '',
  approved_angle: '',
  post_copy: '',
  image_direction: '',
  taylor_approval_round: 0
}}];

const d = $input.first().json;
const feedbackSection = d.sofia_feedback
  ? `
Previous reviewer feedback to address:
${d.sofia_feedback}
`
  : '';

const prompt = `You are Sofia, a content strategy researcher at Relay.

Client: ${d.client_name}
Platform: ${d.platform}
Content Type: ${d.content_type}
Topic Hint: ${d.topic_hint}
Tone Note: ${d.tone_note}

### Brand Context
${d.brand_guide}

### Platform Context
${d.platform_playbook}
${feedbackSection}
Task: Generate exactly 3 content angle options. Each angle must:
1. Be specific and tailored to ${d.platform} audience
2. Reference the brand voice and key messages from Loopin
3. Include a clear rationale explaining why it fits
4. Avoid generic startup clichés

Format response as:
**Angle 1: [Title]**
[1-2 sentence rationale]

**Angle 2: [Title]**
[1-2 sentence rationale]

**Angle 3: [Title]**
[1-2 sentence rationale]`;

return [{ json: { ...d, sofia_prompt: prompt } }];

const apiResp = $input.first().json;
const ctx = $('Build Sofia Prompt').first().json;
const sofia_angles = apiResp.content?.[0]?.text || '';
return [{ json: { ...ctx, sofia_angles } }];

const d = $input.first().json;
const ctx = $('Parse Sofia Output').first().json;

const decision = d.sofia_decision || d.data?.sofia_decision || d.response?.sofia_decision || '';
const notes = d.sofia_notes || d.data?.sofia_notes || d.response?.sofia_notes || '';

return [{ json: { ...ctx, sofia_decision: decision, sofia_notes: notes } }];

const d = $input.first().json;
const decision = d.sofia_decision || '';
let approved_angle = decision.replace(/^Approve:?\s*/i, '').trim();
if (!approved_angle) approved_angle = (d.sofia_angles || '').split('\n')[0];
return [{ json: { ...d, approved_angle, sofia_feedback: '' } }];

const d = $input.first().json;
if ((d.iterations_sofia || 0) >= 3) {
  throw new Error('Sofia revision limit (3) reached. Manual intervention required.');
}
return [{ json: {
  ...d,
  iterations_sofia: (d.iterations_sofia || 0) + 1,
  sofia_feedback: d.sofia_notes || ''
}}];

const d = $input.first().json;
const feedbackSection = d.marcus_feedback
  ? `
Previous feedback to incorporate:
${d.marcus_feedback}
`
  : '';
const platformLimits = {
  'LinkedIn': '800-1500 characters',
  'X (Twitter)': 'max 280 characters (single tweet) or 3-7 tweet thread',
  'Instagram': '200-400 character caption'
};
const charLimit = platformLimits[d.platform] || '800-1200 characters';

const prompt = `You are Marcus, a creative at Relay.

Approved Angle: ${d.approved_angle}
Platform: ${d.platform}
Content Type: ${d.content_type}
Tone: ${d.tone_note}

### Brand Context
${d.brand_guide}

### Platform Context
${d.platform_playbook}
${feedbackSection}
Task: Create a social media post for ${d.platform} based on the approved angle.

**Post Copy Requirements:**
- Length: ${charLimit}
- Hook first
- Tone: ${d.tone_note}
- Loopin voice: clear, direct, human, practical, confident
- End with ONE CTA

**Image Direction Requirements:**
- Be specific (not 'create an image' - describe exactly what to show)
- Reference Loopin brand colors (#5B4AE8 primary, #00D9C8 accent)
- For Instagram: describe each carousel slide individually
- For LinkedIn: describe screenshot, stat graphic, or photo
- For X: optional - only describe if it adds value

Format response EXACTLY as:
**Post Copy:**
[copy here]

**Image Direction:**
[specific visual description]`;

return [{ json: { ...d, marcus_prompt: prompt } }];

const apiResp = $input.first().json;
const ctx = $('Build Marcus Prompt').first().json;
const rawText = apiResp.content?.[0]?.text || '';

const copyMatch = rawText.match(/\*\*Post Copy:\*\*\s*([\s\S]*?)(?=\*\*Image Direction:\*\*|$)/i);
const imgMatch = rawText.match(/\*\*Image Direction:\*\*\s*([\s\S]*?)$/i);

const post_copy = copyMatch ? copyMatch[1].trim() : rawText;
const image_direction = imgMatch ? imgMatch[1].trim() : '(See post copy)';

return [{ json: { ...ctx, post_copy, image_direction } }];

parameters.jsonBody:
={{ JSON.stringify({ model: 'claude-haiku-4-5-20251001', max_tokens: 800, messages: [{ role: 'user', content: `You are Taylor, a content quality reviewer at Relay.

Post copy: ${$json.post_copy}
Image direction: ${$json.image_direction}
Platform: ${$json.platform}
Original brief: ${$json.topic_hint}

### Brand Context
${$json.brand_guide}

### Platform Context
${$json.platform_playbook}

Analyze this and respond ONLY with valid JSON (no markdown, no preamble):
{
  "summary": "2-3 sentence description",
  "quality_flags": ["flag1", "flag2"],
  "recommendation": "approve | needs_revision | reject_to_sofia",
  "reasoning": "brief explanation"
}

Be strict on brand fit.` }] }) }}

